import {DatabaseSync} from 'node:sqlite';
import {readFileSync,mkdtempSync,rmSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
export const time=Date.now();
export function manifest(){return {occurrenceId:crypto.randomUUID(),requestId:crypto.randomUUID(),signal:{version:'afw-assistance-event-v1',eventId:'a'.repeat(64),projectRef:'b'.repeat(64),revision:10,kind:'assistance_requested',topic:'orientation',observedAt:new Date(time-1000).toISOString()},sourceRevision:'8eecaac0dcfca4c5dd2748cd75c8dda5b6cde5cc',configId:'cecfg_synthetic',publicationId:'cecfgver_synthetic',startAt:time-1,deadline:time+120000,tokenExpiresAt:time+120000,serverDeadline:time+120000};}
export function observation(m,t=time){return {sourceRevision:m.sourceRevision,configId:m.configId,publicationId:m.publicationId,origin:'https://github.com/tokenizartinfo-ops/agent-friendly-web.git',observationsCurrent:true,networkMode:'restricted',networkEnforced:true,operationsBindingsReady:true,observationRevision:2,configurationRevision:2,observedAt:t};}
export const schemas=['schema','consumer-state','notice-reservations','dossier-supervision','assistance-supervision','assistance-supervision-runs','assistance-occurrences'];
export function sqlStatements(source){const pattern=/^CREATE TRIGGER\b[\s\S]*?^END;/gm,triggers=source.match(pattern)??[];return [...source.replace(pattern,'').replace(/--[^\n]*/g,'').split(';').map(s=>s.trim()).filter(Boolean),...triggers];}
function wrap(sqlite){const prepare=sql=>{const bind=(values=[])=>({bind:(...next)=>bind(next),first:async()=>sqlite.prepare(sql).get(...values)??null,all:async()=>({results:sqlite.prepare(sql).all(...values)}),run:async()=>({meta:{changes:sqlite.prepare(sql).run(...values).changes}}),execute:()=>/^\s*SELECT\b/i.test(sql)?{results:sqlite.prepare(sql).all(...values)}:{meta:{changes:sqlite.prepare(sql).run(...values).changes}}});return bind();};return {prepare,async batch(statements){sqlite.exec('BEGIN IMMEDIATE');try{const results=statements.map(s=>s.execute());sqlite.exec('COMMIT');return results;}catch(e){sqlite.exec('ROLLBACK');throw e;}}};}
export function fixture(){const root=mkdtempSync(join(tmpdir(),'afw-operations-')),file=join(root,'db.sqlite'),a=new DatabaseSync(file),b=new DatabaseSync(file);a.exec('PRAGMA foreign_keys=ON');b.exec('PRAGMA foreign_keys=ON');for(const name of schemas)a.exec(readFileSync('worker/operations/'+name+'.sql','utf8'));const m=manifest();a.prepare('INSERT INTO assistance_supervision_events VALUES(?,?,?,?,?,?,?)').run(m.signal.eventId,m.signal.projectRef,10,'assistance_requested','orientation',m.signal.observedAt,time);return {a,b,db:wrap(a),other:wrap(b),m,cleanup(){a.close();b.close();rmSync(root,{recursive:true});}};}
